        return False
    lines = text[:-1].split('\n')
    try:
        p = lines[0].split(' ')
        if len(p) != 2 or not all(x.isdigit() and x == str(int(x)) for x in p):
            return False
        h, w = map(int, p)
        if not (1 <= h <= 500 and 1 <= w <= 500) or len(lines) != 2 * h + 2:
