        return False

    def ints(line):
        toks = line.split(" ")
        if any(not t.isdigit() or (len(t) > 1 and t[0] == "0") for t in toks):
            return None
        return list(map(int, toks))

    a, t, o = ints(lines[0]), ints(lines[1]), ints(lines[2])
