def valid(text):
    """题面契约：两行；第一行 n（1<=n<=200）；第二行若干空格分隔整数，本班编号 1..n（互不重复），
    他班编号 n+1..10000（可重复）；保证走丢的和乱入的都至少有一个。"""
    if not text.endswith("\n"):
        return False
    lines = text[:-1].split("\n")
    if len(lines) != 2:
        return False
    try:
        if lines[0].strip() != lines[0] or not lines[0].isdigit():
            return False
        n = int(lines[0])
        toks = lines[1].split(" ")
        if any(not t.isdigit() for t in toks):
            return False
        v = [int(t) for t in toks]
    except ValueError:
        return False
    if not 1 <= n <= 200:
        return False
    if any(x < 1 or x > 10000 for x in v):
        return False
    inside = [x for x in v if x <= n]
    outside = [x for x in v if x > n]
    if len(set(inside)) != len(inside):
        return False
    return len(inside) < n and len(outside) >= 1

def valid(text):
    """题面契约：第一行正整数 n (n<=100)；接下来 n 行，每行 n 个不大于 10000 的非负整数（单空格分隔）。"""
    if not text.endswith("\n"):
        return False
    lines = text[:-1].split("\n")
    if not re.fullmatch(r"[1-9][0-9]*", lines[0]):
        return False
    n = int(lines[0])
    if not 1 <= n <= 100 or len(lines) != n + 1:
        return False
    for line in lines[1:]:
        parts = line.split(" ")
        if len(parts) != n:
            return False
        for p in parts:
            if not re.fullmatch(r"0|[1-9][0-9]*", p) or int(p) > 10000:
                return False
    return True

def valid(text):
    """题面：第一行正整数 n a b（n<=100）；第二行 n 个正整数。
    题面写“a 和 b 均大于任意一株植物”，但样例 1（a=3、植物 3）是等于，原题 LeetCode 2105 为 <=，故按 a,b >= max 校验。"""
    if not text.endswith("\n"):
        return False
    lines = text[:-1].split("\n")
    if len(lines) != 2:
        return False
    head, body = lines[0].split(" "), lines[1].split(" ")
    if len(head) != 3 or not all(re.fullmatch(r"[1-9][0-9]*", x) for x in head + body):
        return False
    n, a, b = map(int, head)
    if not (1 <= n <= 100) or len(body) != n:
        return False
    mx = max(map(int, body))
    return a >= mx and b >= mx

def valid(text):
    """题面：第一行 n m（n<=100，m<=10000）；接下来 m 行 a b c，0<=a,b<=n-1，c∈{0,1}。"""
    if not text.endswith("\n"):
        return False
    lines = text[:-1].split("\n")
    head = lines[0].split(" ")
    if len(head) != 2 or not all(re.fullmatch(r"0|[1-9][0-9]*", x) for x in head):
        return False
    n, m = map(int, head)
    if not (1 <= n <= 100 and 0 <= m <= 10000) or len(lines) != m + 1:
        return False
    for line in lines[1:]:
        parts = line.split(" ")
        if len(parts) != 3 or not all(re.fullmatch(r"0|[1-9][0-9]*", x) for x in parts):
            return False
        a, b, c = map(int, parts)
        if not (0 <= a < n and 0 <= b < n and c in (0, 1)):
            return False
    return True

